import{z as s,x as l,o as a,c as i,q as B,j as r,D as e,d as t,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"结构估计案例与收束","description":"","frontmatter":{"title":"结构估计案例与收束","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/se-case-map.md","filePath":"econ/se-case-map.md","lastUpdated":1791413859000}'),d={name:"econ/se-case-map.md"};function p(c,E,m,C,D,P){const A=l("Mermaid");return a(),i("div",null,[E[2]||(E[2]=B('<h1 id="结构估计案例与收束" tabindex="-1">结构估计案例与收束 <a class="header-anchor" href="#结构估计案例与收束" aria-label="Permalink to &quot;结构估计案例与收束&quot;">​</a></h1><div class="epigraph"><p>每篇结构估计是同一出戏：观测选择，反演不可观测，在均衡与动态里重放未发生的政策；换的只是舞台——产品市场、厂商技术、拍卖场或一台公交车的维修单。</p><footer>—— 据 Berry, Levinsohn and Pakes 1995；Rust 1987；Olley and Pakes 1996；Guerre, Perrigne and Vuong 2000 整理</footer></div><p><a href="/econ/se-validation">上一课</a>给了四层验证协议。本课是「结构估计深化」的最后一课，把七课装置放回它们真正回答过的问题，看哪些环节在案例里反复出现、哪些假设一旦松动就换答案；本课程到此收束。读案例用同一份清单：反事实是什么、不可观测是什么、靠什么变异识别、验证做到哪层。结构估计不是一门技术，是一组可拼装的装置；收束的目的是装回工具箱时知道每个部件的承重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>装置混用或假设漂移时，出错的从来不是数学，是清单缺项。本课以六个经典案例为轴，把「需求与供给」四课与「方法」四课各归各位：每个案例都该能报出反事实、不可观测、变异来源、验证层数四项；报不出的环节，就是它后来挨批评的位置。</p><p><span class="marginnote">术语翻译：「反事实」就是「假如政策变了，本来会发生什么」——没发生过、但模型能重放出来的事。准实验答不了它，因为数据里没有那组对照；结构模型的价值正是把均衡反馈也算进这场重放。</span></p><h3 id="案例走读" tabindex="-1">案例走读 <a class="header-anchor" href="#案例走读" aria-label="Permalink to &quot;案例走读&quot;">​</a></h3><p>汽车（BLP 1995）：随机系数需求、特征工具、Bertrand 供给矩，反事实是合并与贸易冲击对车型与价格的重排；验证靠弹性与加成对表行业常识。麦片（Nevo 2001）：同一装置放到多城市面板回答「市场势力多大」，工具故事重写为跨城市变异——<a href="/econ/se-blp-deep">深入课</a>那句「工具每篇重写」的出处，装置谱系见<a href="/econ/blp-demand">BLP 需求估计</a>。微型面包车（Petrin 2002）：微观二次选择进似然，新品福利不再全靠间接矩——微观数据钳位的原型。公交维护（Rust 1987）：状态是里程，反事实是维护政策，不动点与 CCP 两条算法同答一问。电信设备（Olley–Pakes 1996）：投资反演生产率，退出修正，行业生产率变化拆出再配置——技术边的原型。第一价格拍卖（GPV 2000 及其后续）：出价反演估值，储备价反事实，风险厌恶与内生参与靠 \\(n\\) 的变异钉住。</p><p><span class="marginnote">专利续期（Pakes 1986）是最早的动态结构之一：续费决策反演出专利价值分布，方法上正是动态离散选择，比公交引擎还早一年。案例时间线说明装置是渐进化装出来的，不是一次发明。</span></p>',9)),(a(),r(n,null,{default:e(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E8%A7%82%E6%B5%8B%E9%80%89%E6%8B%A9%3A%20%E4%BB%BD%E9%A2%9D%20%2F%20%E5%87%BA%E4%BB%B7%20%2F%20%E6%8A%95%E5%85%A5%20%2F%20%E6%9B%B4%E6%8D%A2%22%5D%20--%3E%20INV%5B%22%E5%8F%8D%E6%BC%94%E4%B8%8D%E5%8F%AF%E8%A7%82%E6%B5%8B%3A%20%CE%B4%20%2F%20v%20%2F%20%CF%89%20%2F%20EV%22%5D%0A%20%20INV%20--%3E%20EQ%5B%22%E5%9D%87%E8%A1%A1%E6%88%96%E5%8A%A8%E6%80%81%E9%87%8C%E9%87%8D%E6%94%BE%E6%94%BF%E7%AD%96%22%5D%0A%20%20EQ%20--%3E%20CF%5B%22%E5%8F%8D%E4%BA%8B%E5%AE%9E%3A%20%E4%BB%B7%E6%A0%BC%20%2F%20%E7%94%9F%E4%BA%A7%E7%8E%87%20%2F%20%E6%94%B6%E5%85%A5%20%2F%20%E6%9B%B4%E6%8D%A2%E7%8E%87%22%5D%0A%20%20VAL%5B%22%E5%9B%9B%E5%B1%82%E9%AA%8C%E8%AF%81%E5%8D%8F%E8%AE%AE%22%5D%20--%3E%20CF%0A%20%20LIST%5B%22%E6%A1%88%E4%BE%8B%E6%B8%85%E5%8D%95%3A%20%E5%8F%8D%E4%BA%8B%E5%AE%9E%C2%B7%E5%8F%98%E5%BC%82%C2%B7%E9%AA%8C%E8%AF%81%22%5D%20--%3E%20OBS%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把收束写成一页判据。何时用结构：反事实区域在观测支持外（新政策、新规则、未发生过的合并），或对象本身是不可观测的原语（估值、生产率、折现）。何时用设计：问题在支撑内、可信对照存在时，<a href="/econ/potential-outcomes">潜在结果</a>框架下的准实验答案更便宜也更少争议。两者的接口在<a href="/econ/structural-vs-reduced">结构对约化形式</a>：结构解释设计为何失效，设计给结构提供伪反事实的对表锚点。方法四课是工程件：贝叶斯换估计原则，SMM 管积分，验证管外推的口气，任何一个需求与供给装置都能拆下来换装。</p><p><span class="marginnote">直觉类比：读一篇结构论文像起飞前过检查单——反事实是什么（去哪）、不可观测是什么（仪表上没有的量）、靠什么变异识别（推力从哪来）、验证做到哪层（哪些仪表校过）。四项有一项含糊，落地前就该犹豫。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>六案例的公共机制有三条。其一，「变异换识别」：需求靠市场截面与微观数据，动态靠转移与跨期变异，技术靠投入对生产率的单调反应，拍卖靠人数与规则变异。其二，「选择层先行」：退出、进入、参与，先钉住选择层再反演，反演对象才不混策略。其三，「验证约束外推」：案例的说服力从拟合优度移到伪反事实与样本外——这是三十年方法演化的主线，也是下一阶段结构研究的入场券。</p>',5)),(a(),r(n,null,{default:e(()=>[o(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20BLP%5B%22%E6%B1%BD%E8%BD%A6%20BLP%22%5D%20--%3E%7C%22%E5%B8%82%E5%9C%BA%E6%88%AA%E9%9D%A2%E7%89%B9%E5%BE%81%E5%8F%98%E5%BC%82%22%7C%20COM%5B%22%E9%9C%80%E6%B1%82%E8%A3%85%E7%BD%AE%22%5D%0A%20%20NEVO%5B%22%E9%BA%A6%E7%89%87%20Nevo%22%5D%20--%3E%7C%22%E8%B7%A8%E5%9F%8E%E5%B8%82%E4%BB%B7%E6%A0%BC%E5%8F%98%E5%BC%82%22%7C%20COM%0A%20%20PETRIN%5B%22%E9%9D%A2%E5%8C%85%E8%BD%A6%20Petrin%22%5D%20--%3E%7C%22%E5%BE%AE%E8%A7%82%E4%BA%8C%E6%AC%A1%E9%80%89%E6%8B%A9%22%7C%20TAIL%5B%22%E5%88%86%E5%B8%83%E5%B0%BE%E9%83%A8%E9%92%B3%E4%BD%8D%22%5D%0A%20%20RUST%5B%22%E5%85%AC%E4%BA%A4%20Rust%22%5D%20--%3E%7C%22%E9%87%8C%E7%A8%8B%E8%BD%AC%E7%A7%BB%E5%8F%98%E5%BC%82%22%7C%20DYN%5B%22%E5%8A%A8%E6%80%81%E8%A3%85%E7%BD%AE%22%5D%0A%20%20OP%5B%22%E7%94%B5%E4%BF%A1%20Olley-Pakes%22%5D%20--%3E%7C%22%E6%8A%95%E5%85%A5%E5%AF%B9%E7%94%9F%E4%BA%A7%E7%8E%87%E7%9A%84%E5%8D%95%E8%B0%83%E5%8F%8D%E5%BA%94%22%7C%20TECH%5B%22%E6%8A%80%E6%9C%AF%E8%A3%85%E7%BD%AE%22%5D%0A%20%20GPV%5B%22%E6%8B%8D%E5%8D%96%20GPV%22%5D%20--%3E%7C%22%E4%BA%BA%E6%95%B0%E4%B8%8E%E8%A7%84%E5%88%99%E5%8F%98%E5%BC%82%22%7C%20GAME%5B%22%E5%8D%9A%E5%BC%88%E5%8F%8D%E6%BC%94%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">常见误区：初学者容易把「结构模型算出了精确数字」当成可信的证据。案例里的数字绑定当时的数据与环境；搬用的正确姿势是重验装置——工具、市场定义、验证层数逐项过一遍，而不是直接引用当年的弹性或价格预测。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束不宣称结构普适：设计能答的别上结构；结构能答的别用设计硬凑。案例数字依赖当时的数据与环境，搬用前重验装置。本深钻课到此收口，知识树随后进入下一门深钻课；五栏主干在各自课程里继续延伸。</p><p>后课默认（本课程到此收束）：遇到反事实问题，先过案例清单——反事实、不可观测、变异、验证四项写得清，再挑装置；清单写不清的问题，结构估计救不了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>案例公共骨架：观测选择 → 反演不可观测 → 均衡与动态重放 → 验证。</li><li>BLP、Nevo、Petrin 管需求；Rust、Pakes 管动态；Olley–Pakes 管技术；GPV 管博弈场。</li><li>变异换识别，选择层先行，验证约束外推。</li><li>支撑内的问题优先找设计，支撑外的问题才动结构。</li><li>本课程「结构估计深化」到此收束：八课一具工具箱，部件承重各记其账。</li><li>出处：BLP, <em>Econometrica</em> 1995；Nevo, <em>Econometrica</em> 2001；Petrin, <em>Econometrica</em> 2002；Rust, <em>Econometrica</em> 1987；Pakes, <em>Econometrica</em> 1986；Olley and Pakes, <em>Econometrica</em> 1996；Guerre, Perrigne and Vuong, <em>Econometrica</em> 2000。</li></ul>',6))])}const u=s(d,[["render",p]]);export{_ as __pageData,u as default};
